// Discord.js v14 Code:
const { Client, GatewayIntentBits, Interaction } = require('discord.js');
const { Application, Permissions } = require('discord.js');

// Create a new Discord bot client
const client = new Client({ intents: [GatewayIntentBits.Guilds] });

// Event listener for interactions
client.on('interactionCreate', async interaction => {
    // If the interaction is a command, check if it's the "ban" command
    if (interaction.isCommand()) {
        if (interaction.commandName === 'ban') {
            // Get the member to ban
            const member = interaction.options.getMember('member', true);

            // Check if the member is banned
            if (member.banned) {
                // Reply with an error message
                await interaction.reply({
                    content: `Member ${member.user.username} is already banned`,
                    ephemeral: true
                });
            } else {
                // Ban the member
                await member.banned = true;

                // Reply with a success message
                await interaction.reply({
                    content: `Member ${member.user.username} has been banned`,
                    ephemeral: true
                });
            }
        }
    }
});

// Login the bot and start the event listeners
client.login('YOUR_TOKEN');assistant

This code creates a Discord bot that uses Discord.js v14. It has a single command, ban, which bans the mentioned member from the server. The bot also has event listeners for interactions, which check if the interaction is a command. If it is, it checks if the command name is "ban". If so, it gets the member to ban and checks if they are already banned. If they are not, it bans them and replies with a success message. Otherwise, it replies with an error message. Finally, the bot logs in and starts listening for interactions.assistant

