/* Program to calculate the total cost of a grocery shopping list */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct item {
    char name[20];
    float price;
    int quantity;
};

int main() {
    // Declare variables
    int i, n;
    float total_cost = 0.0;

    // Get input
    printf("Enter the number of items in your shopping list: ");
    scanf("%d", &n);
    struct item list[n];

    for (i = 0; i < n; i++) {
        printf("Enter name, price, and quantity of item %d: ", i+1);
        scanf("%s %f %d", list[i].name, &list[i].price, &list[i].quantity);
    }

    // Calculate total cost
    for (i = 0; i < n; i++) {
        total_cost += list[i].quantity * list[i].price;
    }

    // Print output
    printf("Total cost: $%.2f", total_cost); return 0; }user

